materials.css:
@font-face {
  font-family: 'Noto Serif SC';
  font-style: normal;
  font-weight: 400;
  src: url('https://fonts.gstatic.com/s/notoserifsc/v22/H4chBXePl9DZ0Xe7gG9cyOj7oqCcbzhqDtg.woff2') format('woff2');
  font-display: swap;
}
@font-face {
  font-family: 'Noto Serif SC';
  font-style: normal;
  font-weight: 600;
  src: url('https://fonts.gstatic.com/s/notoserifsc/v22/H4chBXePl9DZ0Xe7gG9cyOj7oqCcbzhqDtg.woff2') format('woff2');
  font-display: swap;
}
@font-face {
  font-family: 'Noto Serif SC';
  font-style: normal;
  font-weight: 900;
  src: url('https://fonts.gstatic.com/s/notoserifsc/v22/H4chBXePl9DZ0Xe7gG9cyOj7oqCcbzhqDtg.woff2') format('woff2');
  font-display: swap;
}
@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 400;
  src: url('https://fonts.gstatic.com/s/ibmplexmono/v19/-F6qfjptAgt5VM-kVkqdyU8n1iI.woff2') format('woff2');
  font-display: swap;
}

.mix-game {
  color: #e0d8cd;
  --ink: #e0d8cd;
  --ink-soft: #c9bfb2;
  --ink-faint: #9a8f81;
  --cinnabar: #b84935;
  --gold: #a68a56;
  --line: rgba(230, 217, 198, 0.14);
  --bubble-user: #2d2620;
  --bubble-ai: #26201b;
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'STZhongsong', 'SimSun', serif;
}

/* 封面背景层：只保留原始显示，不写 background，避免覆盖 background-size */
.mix-game-bg {
  opacity: 1;
}

/* 标题栏：只上色，不改变高度、内边距、定位与按钮布局 */
.mix-game-header {
  background-color: #2d2620;
  border-bottom: 1px solid var(--line);
}

.mix-game-title {
  color: var(--ink);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 4px;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}

.mix-icon-btn {
  color: var(--ink-faint);
  background-color: transparent;
  border: none;
  border-radius: 4px;
  font-size: 13px;
  transition: color 0.2s ease, background-color 0.2s ease;
  pointer-events: auto;
}

.mix-icon-btn:hover {
  color: var(--cinnabar);
  background-color: rgba(184, 73, 53, 0.08);
}

/* ★ 状态条优化：铺满全宽，且不遮挡按钮 */
/* 注意：状态条原本是在标题栏下方，要让它铺满，需要确保它没有被父容器限制左右 padding */
/* 这里我们把左右 margin 设为负值来突破父容器的 padding，再用对应的 padding 补回来 */
.mix-state-bar {
  background-color: #2d2620;
  border-bottom: 1px solid var(--line);
  /* 突破父级可能存在的 15px padding */
  margin: 0 -15px; 
  /* 左右补回内边距，保证文字不贴边，上下留白 */
  padding: 6px 15px; 
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  /* 保证层级，并且能点到 */
  position: relative; 
  z-index: 10;
  pointer-events: auto;
}

.mix-state-chip {
  background-color: rgba(184, 73, 53, 0.1);
  color: var(--ink-soft);
  border: 1px solid rgba(184, 73, 53, 0.2);
  border-radius: 3px;
  padding: 3px 8px;
  font-size: 11px;
  letter-spacing: 1px;
  font-family: 'IBM Plex Mono', 'Courier New', monospace;
  /* 增加可点击属性（如果它绑定了事件的话） */
  cursor: pointer;
  transition: all 0.2s ease;
}

.mix-state-chip:hover {
  background-color: rgba(184, 73, 53, 0.2);
  color: var(--ink);
}

/* 对话滚动区 */
.mix-game-scroll {
  background-color: transparent;
  scrollbar-width: thin;
  scrollbar-color: var(--line) transparent;
  padding: 12px 14px 24px 14px;
}

.mix-game-scroll::-webkit-scrollbar {
  width: 5px;
}

.mix-game-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.mix-game-scroll::-webkit-scrollbar-thumb {
  background: rgba(184, 73, 53, 0.35);
  border-radius: 3px;
}

.mix-user-turn {
  margin: 10px 0 16px 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding-left: 36px;
}

.mix-user-bubble {
  background-color: var(--bubble-user);
  color: var(--ink);
  border: 1px solid rgba(184, 73, 53, 0.28);
  border-radius: 12px 4px 12px 12px;
  padding: 10px 14px;
  font-size: 14px;
  line-height: 1.8;
  letter-spacing: 0.5px;
  position: relative;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.mix-user-bubble::after {
  content: '';
  position: absolute;
  right: -1px;
  top: 0;
  width: 2px;
  height: 100%;
  background-color: rgba(184, 73, 53, 0.45);
  border-radius: 0 12px 12px 0;
}

.mix-assistant-turn {
  margin: 10px 0 16px 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding-right: 24px;
}

.mix-assistant-turn > .mix-para, .mix-assistant-turn > .mix-narration, .mix-assistant-turn > .mix-scene, .mix-assistant-turn > .mix-dialogue, .mix-assistant-turn > .mix-thought {
  background-color: var(--bubble-ai);
  border: 1px solid var(--line);
  border-radius: 4px 12px 12px 12px;
  padding: 10px 14px;
  margin: 0 0 6px 0;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.85;
  letter-spacing: 0.5px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
  position: relative;
}

.mix-assistant-turn > .mix-para:first-child::before, .mix-assistant-turn > .mix-narration:first-child::before {
  content: '';
  position: absolute;
  left: -1px;
  top: 0;
  width: 2px;
  height: 100%;
  background-color: rgba(184, 73, 53, 0.5);
  border-radius: 12px 0 0 12px;
}

.mix-prose {
  color: var(--ink);
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'STZhongsong', 'SimSun', serif;
  font-size: 14.5px;
  line-height: 1.9;
  letter-spacing: 0.6px;
}

.mix-para {
  color: var(--ink);
  text-indent: 2em;
  margin: 0 0 8px 0;
  font-size: 14.5px;
  line-height: 1.9;
  letter-spacing: 0.6px;
}

.mix-narration {
  color: var(--ink-soft);
  font-size: 13.5px;
  line-height: 1.85;
  letter-spacing: 0.5px;
}

.mix-scene {
  color: var(--cinnabar);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 2px;
  text-align: center;
  margin: 12px 0;
  padding: 4px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.mix-scene::before {
  content: '◆ ';
  color: var(--gold);
  font-size: 10px;
}

.mix-scene::after {
  content: ' ◆';
  color: var(--gold);
  font-size: 10px;
}

.mix-dialogue {
  color: var(--ink);
  font-size: 14.5px;
  line-height: 1.85;
  letter-spacing: 0.5px;
  margin: 6px 0;
  padding-left: 10px;
  border-left: 2px solid rgba(184, 73, 53, 0.4);
}

.mix-thought {
  color: var(--ink-faint);
  font-style: italic;
  font-size: 13.5px;
  line-height: 1.8;
  letter-spacing: 0.5px;
  opacity: 0.85;
}

.mix-accent {
  color: var(--cinnabar);
  font-weight: 600;
  letter-spacing: 0.5px;
}

.mix-turn-act {
  opacity: 0.55;
  transition: opacity 0.2s ease;
  gap: 4px;
}

.mix-turn-act:hover {
  opacity: 1;
}

.mix-turn-act button {
  color: var(--ink-faint);
  background-color: transparent;
  border: none;
  font-size: 11px;
  cursor: pointer;
  padding: 3px 6px;
  border-radius: 3px;
  transition: color 0.2s ease;
}

.mix-turn-act button:hover {
  color: var(--cinnabar);
}

.mix-game-inputbar {
  background-color: #2d2620;
  border-top: 1px solid var(--line);
  padding: 10px 12px;
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
}

.mix-game-input {
  background-color: #241f1a;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 9px 12px;
  font-size: 14px;
  line-height: 1.7;
  letter-spacing: 0.5px;
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'STZhongsong', 'SimSun', serif;
  outline: none;
  transition: border-color 0.2s ease;
  flex: 1;
  min-width: 0;
}

.mix-game-input:focus {
  border-color: rgba(184, 73, 53, 0.5);
}

.mix-game-input::placeholder {
  color: var(--ink-faint);
  opacity: 0.7;
  letter-spacing: 1px;
}

.mix-send-btn {
  background-color: rgba(184, 73, 53, 0.2);
  color: var(--cinnabar);
  border: 1px solid rgba(184, 73, 53, 0.35);
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'STZhongsong', 'SimSun', serif;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
  min-height: 36px;
}

.mix-send-btn:hover {
  background-color: rgba(184, 73, 53, 0.35);
  color: #f0e0d8;
}

.mix-send-btn:active {
  background-color: rgba(184, 73, 53, 0.45);
}

.mix-ticket-wrap {
  margin: 6px 0 10px 0;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.35);
}

.mix-encore-inline {
  background-color: rgba(184, 73, 53, 0.06);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 10px;
  margin: 8px 0;
}

.mix-game-thinking {
  color: var(--ink-faint);
  font-size: 12.5px;
  letter-spacing: 2px;
  font-family: 'IBM Plex Mono', 'Courier New', monospace;
  padding: 6px 2px;
  opacity: 0.7;
}
